package com.kclog;

import net.runelite.client.config.*;

@ConfigGroup(KcLogConfig.GROUP)
public interface KcLogConfig extends Config
{
	String GROUP = "kclog";

	@ConfigItem(keyName = "chatMessage", name = "Chat message on kill", description = "Show your new kill count in chat after each kill")
	default boolean chatMessage() { return false; }

	@ConfigItem(keyName = "historyDays", name = "Daily history days", description = "How many days of per-day kill counts to keep")
	@Range(min = 1, max = 365)
	default int historyDays() { return 30; }
}

package com.kclog;

import java.awt.BasicStroke;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.text.NumberFormat;
import java.util.Locale;
import java.util.Map;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.Icon;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.JScrollPane;
import javax.swing.JTabbedPane;
import javax.swing.JTextField;
import javax.swing.ScrollPaneConstants;
import javax.swing.border.EmptyBorder;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

class KcLogPanel extends PluginPanel
{
	private final KcLogPlugin plugin;
	private final JPanel allTimeList = newList();
	private final JPanel todayList = newList();
	private final JLabel total = new JLabel("0");
	private final JLabel caption = new JLabel("TOTAL KILLS");
	private final JLabel monsters = new JLabel("0 creatures");
	private final JTextField search = new JTextField();
	private final JTabbedPane tabs = new JTabbedPane();
	private final NumberFormat numbers = NumberFormat.getIntegerInstance();
	private Map<String, Integer> allTime = Map.of();
	private Map<String, Integer> today = Map.of();

	KcLogPanel(KcLogPlugin plugin)
	{
		this.plugin = plugin;
		setLayout(new BorderLayout(0, 12));
		setBorder(new EmptyBorder(14, 10, 10, 10));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel top = new JPanel();
		top.setOpaque(false);
		top.setLayout(new BoxLayout(top, BoxLayout.Y_AXIS));
		JLabel title = new JLabel("KC LOG");
		title.setFont(FontManager.getDefaultBoldFont().deriveFont(16f));
		title.setForeground(ColorScheme.TEXT_COLOR);
		top.add(title);
		top.add(Box.createVerticalStrut(18));

		caption.setFont(FontManager.getDefaultFont().deriveFont(10f));
		caption.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		top.add(caption);
		total.setFont(FontManager.getDefaultBoldFont().deriveFont(30f));
		total.setForeground(ColorScheme.BRAND_ORANGE);
		top.add(total);
		monsters.setFont(FontManager.getDefaultFont().deriveFont(11f));
		monsters.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		top.add(monsters);
		top.add(Box.createVerticalStrut(14));

		JPanel searchBar = new JPanel(new BorderLayout(8, 0));
		searchBar.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		searchBar.setBorder(new EmptyBorder(8, 8, 8, 8));
		searchBar.add(new JLabel(new SearchIcon()), BorderLayout.WEST);
		search.setFont(FontManager.getDefaultFont());
		search.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		search.setForeground(ColorScheme.TEXT_COLOR);
		search.setCaretColor(ColorScheme.TEXT_COLOR);
		search.setBorder(null);
		search.setToolTipText("Search creatures");
		search.getAccessibleContext().setAccessibleName("Search creatures");
		search.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override public void insertUpdate(DocumentEvent e) { rebuild(); }
			@Override public void removeUpdate(DocumentEvent e) { rebuild(); }
			@Override public void changedUpdate(DocumentEvent e) { rebuild(); }
		});
		searchBar.add(search, BorderLayout.CENTER);
		top.add(searchBar);
		for (Component component : top.getComponents())
		{
			if (component instanceof javax.swing.JComponent)
			{
				((javax.swing.JComponent) component).setAlignmentX(LEFT_ALIGNMENT);
			}
		}
		add(top, BorderLayout.NORTH);

		tabs.setUI(new javax.swing.plaf.basic.BasicTabbedPaneUI()
		{
			@Override protected void installDefaults()
			{
				super.installDefaults();
				lightHighlight = ColorScheme.BORDER_COLOR;
				shadow = ColorScheme.DARK_GRAY_COLOR;
				darkShadow = ColorScheme.DARK_GRAY_COLOR;
				focus = ColorScheme.BRAND_ORANGE;
			}

			@Override protected void paintTabBackground(Graphics g, int placement, int index, int x, int y, int w, int h, boolean selected)
			{
				g.setColor(selected ? ColorScheme.DARKER_GRAY_COLOR : ColorScheme.DARK_GRAY_COLOR);
				g.fillRect(x, y, w, h);
			}

			@Override protected void paintText(Graphics g, int placement, java.awt.Font font, java.awt.FontMetrics fm, int index, String text, java.awt.Rectangle rect, boolean selected)
			{
				g.setFont(font);
				g.setColor(selected ? ColorScheme.BRAND_ORANGE : ColorScheme.LIGHT_GRAY_COLOR);
				g.drawString(text, rect.x, rect.y + fm.getAscent());
			}
		});
		tabs.addTab("All time", scroll(allTimeList));
		tabs.addTab("Today", scroll(todayList));
		tabs.setFont(FontManager.getDefaultBoldFont().deriveFont(12f));
		tabs.setForeground(ColorScheme.TEXT_COLOR);
		tabs.setBackground(ColorScheme.DARK_GRAY_COLOR);
		tabs.addChangeListener(e -> rebuild());
		add(tabs, BorderLayout.CENTER);

		JButton resetAll = new JButton("Reset all counts");
		resetAll.setUI(new javax.swing.plaf.basic.BasicButtonUI());
		resetAll.setBorder(new EmptyBorder(9, 6, 9, 6));
		resetAll.setFocusPainted(false);
		resetAll.setFont(FontManager.getDefaultFont().deriveFont(11f));
		resetAll.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		resetAll.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		resetAll.addActionListener(e ->
		{
			if (JOptionPane.showConfirmDialog(this, "Reset all-time and daily counts for every creature?", "Reset KC Log", JOptionPane.YES_NO_OPTION) == JOptionPane.YES_OPTION)
			{
				plugin.reset(null);
			}
		});
		JPanel footer = new JPanel(new BorderLayout());
		footer.setOpaque(false);
		footer.add(resetAll, BorderLayout.CENTER);
		add(footer, BorderLayout.SOUTH);
		rebuild();
	}

	private static JPanel newList()
	{
		JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setOpaque(false);
		return panel;
	}

	private static JScrollPane scroll(javax.swing.JComponent component)
	{
		JScrollPane scrollPane = new JScrollPane(component, ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED, ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scrollPane.setBorder(new EmptyBorder(8, 0, 0, 0));
		scrollPane.setViewportBorder(null);
		scrollPane.setOpaque(false);
		scrollPane.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
		scrollPane.getVerticalScrollBar().setUnitIncrement(24);
		return scrollPane;
	}

	void update(Map<String, Integer> allTime, Map<String, Integer> today)
	{
		this.allTime = allTime;
		this.today = today;
		rebuild();
	}

	private void rebuild()
	{
		fill(todayList, today, true);
		fill(allTimeList, allTime, false);
		Map<String, Integer> shown = tabs.getSelectedIndex() == 1 ? today : allTime;
		total.setText(numbers.format(shown.values().stream().mapToLong(Integer::longValue).sum()));
		caption.setText(tabs.getSelectedIndex() == 1 ? "KILLS TODAY" : "TOTAL KILLS");
		monsters.setText(numbers.format(shown.size()) + (shown.size() == 1 ? " creature" : " creatures"));
	}

	private void fill(JPanel target, Map<String, Integer> data, boolean isToday)
	{
		target.removeAll();
		String query = search.getText().trim().toLowerCase(Locale.ROOT);
		data.entrySet().stream()
			.filter(entry -> entry.getKey().toLowerCase(Locale.ROOT).contains(query))
			.sorted((a, b) ->
			{
				int comparison = Integer.compare(b.getValue(), a.getValue());
				return comparison != 0 ? comparison : a.getKey().compareToIgnoreCase(b.getKey());
			})
			.forEach(entry ->
			{
				target.add(row(entry.getKey(), entry.getValue()));
				target.add(Box.createVerticalStrut(4));
			});

		if (target.getComponentCount() == 0)
		{
			JLabel empty = new JLabel(data.isEmpty() ? (isToday ? "No kills today yet" : "No kills logged yet") : "No matching creatures");
			empty.setFont(FontManager.getDefaultFont().deriveFont(12f));
			empty.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			empty.setBorder(new EmptyBorder(18, 6, 18, 6));
			empty.setAlignmentX(LEFT_ALIGNMENT);
			target.add(empty);
		}
		target.revalidate();
		target.repaint();
	}

	private JPanel row(String name, int count)
	{
		JPanel row = new JPanel(new BorderLayout(7, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(new EmptyBorder(8, 8, 8, 8));

		JPanel words = new JPanel(new BorderLayout(4, 0));
		words.setOpaque(false);
		JLabel label = new JLabel(name);
		label.setFont(FontManager.getDefaultFont().deriveFont(12f));
		label.setForeground(ColorScheme.TEXT_COLOR);
		words.add(label, BorderLayout.CENTER);
		JLabel countLabel = new JLabel(numbers.format(count));
		countLabel.setFont(FontManager.getDefaultBoldFont().deriveFont(13f));
		countLabel.setForeground(ColorScheme.BRAND_ORANGE);
		countLabel.setBorder(new EmptyBorder(0, 6, 0, 0));
		words.add(countLabel, BorderLayout.EAST);
		row.add(words, BorderLayout.CENTER);

		row.setToolTipText(name + " · " + numbers.format(count) + (count == 1 ? " kill" : " kills"));
		JPopupMenu menu = new JPopupMenu();
		JMenuItem reset = new JMenuItem("Reset " + name);
		reset.addActionListener(e ->
		{
			if (JOptionPane.showConfirmDialog(this, "Reset all-time and daily counts for " + name + "?", "Reset creature", JOptionPane.YES_NO_OPTION) == JOptionPane.YES_OPTION)
			{
				plugin.reset(name);
			}
		});
		menu.add(reset);
		row.setComponentPopupMenu(menu);
		inheritMenu(row);
		row.setAlignmentX(LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 44));
		row.setPreferredSize(new Dimension(190, 44));
		row.setMinimumSize(new Dimension(0, 44));
		return row;
	}

	private static void inheritMenu(Container parent)
	{
		for (Component component : parent.getComponents())
		{
			if (component instanceof javax.swing.JComponent)
			{
				((javax.swing.JComponent) component).setInheritsPopupMenu(true);
				if (component instanceof Container)
				{
					inheritMenu((Container) component);
				}
			}
		}
	}

	private static final class SearchIcon implements Icon
	{
		@Override public int getIconWidth() { return 14; }
		@Override public int getIconHeight() { return 14; }

		@Override
		public void paintIcon(Component component, Graphics graphics, int x, int y)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setColor(ColorScheme.LIGHT_GRAY_COLOR);
			g.setStroke(new BasicStroke(1.5f));
			g.drawOval(x + 1, y + 1, 8, 8);
			g.drawLine(x + 8, y + 8, x + 12, y + 12);
			g.dispose();
		}
	}
}

package com.kclog;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@PluginDescriptor(name = "KC Log", description = "Tracks monster kill counts reported by RuneLite", tags = {"kc", "kill", "count", "today"})
public class KcLogPlugin extends Plugin
{
	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private ConfigManager configManager;
	@Inject private ClientToolbar clientToolbar;
	@Inject private KcLogConfig config;
	@Inject private Gson gson;

	private final KillStore store = new KillStore();
	private KcLogPanel panel;
	private NavigationButton navButton;
	private Timer dayRolloverTimer;
	private String lastDate = LocalDate.now().toString();

	@Provides
	KcLogConfig provideConfig(ConfigManager cm)
	{
		return cm.getConfig(KcLogConfig.class);
	}

	@Override
	protected void startUp()
	{
		panel = new KcLogPanel(this);
		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
		navButton = NavigationButton.builder().tooltip("KC Log").icon(icon).priority(7).panel(panel).build();
		clientToolbar.addNavigation(navButton);
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			load();
		}

		// Midnight can pass while the game is open, so re-check the date once a minute.
		dayRolloverTimer = new Timer(60_000, e -> clientThread.invokeLater(() ->
		{
			String now = LocalDate.now().toString();
			if (!now.equals(lastDate))
			{
				lastDate = now;
				prune();
				save();
				refresh();
			}
		}));
		dayRolloverTimer.start();
	}

	@Override
	protected void shutDown()
	{
		if (dayRolloverTimer != null)
		{
			dayRolloverTimer.stop();
			dayRolloverTimer = null;
		}
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		panel = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		if (e.getGameState() == GameState.LOGGED_IN)
		{
			load();
		}
	}

	/** Records kills when RuneLite reports loot for an NPC. */
	@Subscribe
	public void onNpcLootReceived(NpcLootReceived e)
	{
		NPC npc = e.getNpc();
		if (npc == null || npc.getName() == null)
		{
			return;
		}

		String name = npc.getName();
		String date = LocalDate.now().toString();
		lastDate = date;
		store.record(name, date);
		prune();
		save();
		refresh();
		if (config.chatMessage())
		{
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Your " + name + " kill count is: " + store.all().get(name) + ".", null);
		}
	}

	private void load()
	{
		// Clear in-memory state first so switching accounts cannot retain the previous profile's counts.
		store.resetAll();
		String json = configManager.getRSProfileConfiguration(KcLogConfig.GROUP, "kills");
		if (json != null && !json.isEmpty())
		{
			Map<String, Integer> parsed = parseCounts(json);
			store.replaceAllKills(parsed);
		}

		String dailyJson = configManager.getRSProfileConfiguration(KcLogConfig.GROUP, "daily");
		if (dailyJson != null && !dailyJson.isEmpty())
		{
			store.replaceAllDaily(parseDailyCounts(dailyJson));
		}

		lastDate = LocalDate.now().toString();
		prune();
		refresh();
	}

	private Map<String, Integer> parseCounts(String json)
	{
		Map<String, Integer> counts = new HashMap<>();
		try
		{
			JsonObject object = new JsonParser().parse(json).getAsJsonObject();
			for (Map.Entry<String, JsonElement> entry : object.entrySet())
			{
				if (entry.getValue() != null && entry.getValue().isJsonPrimitive() && entry.getValue().getAsJsonPrimitive().isNumber())
				{
					int count = entry.getValue().getAsInt();
					if (count >= 0)
					{
						counts.put(entry.getKey(), count);
					}
				}
			}
		}
		catch (RuntimeException ignored)
		{
			// Ignore malformed saved data instead of preventing the plugin from starting.
		}
		return counts;
	}

	private Map<String, Map<String, Integer>> parseDailyCounts(String json)
	{
		Map<String, Map<String, Integer>> result = new HashMap<>();
		try
		{
			JsonObject dates = new JsonParser().parse(json).getAsJsonObject();
			for (Map.Entry<String, JsonElement> dateEntry : dates.entrySet())
			{
				if (dateEntry.getValue() != null && dateEntry.getValue().isJsonObject())
				{
					Map<String, Integer> counts = new HashMap<>();
					for (Map.Entry<String, JsonElement> countEntry : dateEntry.getValue().getAsJsonObject().entrySet())
					{
						JsonElement value = countEntry.getValue();
						if (value != null && value.isJsonPrimitive() && value.getAsJsonPrimitive().isNumber())
						{
							int count = value.getAsInt();
						if (count >= 0)
						{
							counts.put(countEntry.getKey(), count);
						}
						}
					}
					result.put(dateEntry.getKey(), counts);
				}
			}
		}
		catch (RuntimeException ignored)
		{
			// Ignore malformed saved data instead of preventing the plugin from starting.
		}
		return result;
	}

	private void prune()
	{
		int days = Math.max(1, config.historyDays());
		store.pruneBefore(LocalDate.now().minusDays(days - 1L).toString());
	}

	private void save()
	{
		configManager.setRSProfileConfiguration(KcLogConfig.GROUP, "kills", gson.toJson(store.all()));
		configManager.setRSProfileConfiguration(KcLogConfig.GROUP, "daily", gson.toJson(store.daily()));
	}

	void reset(String name)
	{
		clientThread.invokeLater(() ->
		{
			if (name == null)
			{
				store.resetAll();
			}
			else
			{
				store.reset(name);
			}
			save();
			refresh();
		});
	}

	private void refresh()
	{
		Map<String, Integer> all = store.all();
		Map<String, Integer> today = store.day(LocalDate.now().toString());
		KcLogPanel currentPanel = panel;
		if (currentPanel != null)
		{
			SwingUtilities.invokeLater(() ->
			{
				if (panel == currentPanel)
				{
					currentPanel.update(all, today);
				}
			});
		}
	}
}

package com.kclog;

import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;

/**
 * Kill counts held in memory: an all-time total per monster, plus a per-day
 * breakdown keyed by ISO date (yyyy-MM-dd) so the panel can show a "Today" view.
 */
final class KillStore
{
	private final Map<String, Integer> kills = new HashMap<>();
	private final Map<String, Map<String, Integer>> daily = new TreeMap<>();

	synchronized void record(String monster, String date)
	{
		kills.merge(monster, 1, Integer::sum);
		daily.computeIfAbsent(date, d -> new HashMap<>()).merge(monster, 1, Integer::sum);
	}

	synchronized Map<String, Integer> all()
	{
		return new HashMap<>(kills);
	}

	synchronized Map<String, Integer> day(String date)
	{
		Map<String, Integer> d = daily.get(date);
		return d == null ? new HashMap<>() : new HashMap<>(d);
	}

	synchronized Map<String, Map<String, Integer>> daily()
	{
		Map<String, Map<String, Integer>> copy = new TreeMap<>();
		for (Map.Entry<String, Map<String, Integer>> en : daily.entrySet())
		{
			copy.put(en.getKey(), new HashMap<>(en.getValue()));
		}
		return copy;
	}

	synchronized int totalKills()
	{
		return kills.values().stream().mapToInt(Integer::intValue).sum();
	}

	synchronized void replaceAllKills(Map<String, Integer> newKills)
	{
		kills.clear();
		if (newKills != null) kills.putAll(newKills);
	}

	synchronized void replaceAllDaily(Map<String, ? extends Map<String, Integer>> newDaily)
	{
		daily.clear();
		if (newDaily == null) return;
		for (Map.Entry<String, ? extends Map<String, Integer>> en : newDaily.entrySet())
		{
			if (en.getKey() != null && en.getValue() != null)
			{
				daily.put(en.getKey(), new HashMap<>(en.getValue()));
			}
		}
	}

	/**
	 * Drop day buckets strictly older than cutoffDate. ISO dates sort as strings,
	 * so a plain string compare is enough here.
	 */
	synchronized void pruneBefore(String cutoffDate)
	{
		daily.keySet().removeIf(date -> date.compareTo(cutoffDate) < 0);
	}

	synchronized void reset(String monster)
	{
		kills.remove(monster);
		for (Map<String, Integer> day : daily.values()) day.remove(monster);
	}

	synchronized void resetAll()
	{
		kills.clear();
		daily.clear();
	}
}

package com.kclog;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class KcLogPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(KcLogPlugin.class);
		RuneLite.main(args);
	}
}

package com.kclog;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class KillStoreTest
{
	@Test
	public void todayCountsAreSeparateFromAllTime()
	{
		KillStore s = new KillStore();
		s.record("Goblin", "2026-10-24");
		s.record("Goblin", "2026-10-24");
		s.record("Goblin", "2026-10-25");

		assertEquals(3, s.all().get("Goblin").intValue());
		assertEquals(2, s.day("2026-10-24").get("Goblin").intValue());
		assertEquals(1, s.day("2026-10-25").get("Goblin").intValue());
	}

	@Test
	public void newDayStartsAtZero()
	{
		KillStore s = new KillStore();
		s.record("Goblin", "2026-10-24");
		assertTrue(s.day("2026-10-25").isEmpty());
		assertEquals(1, s.all().get("Goblin").intValue());
	}

	@Test
	public void pruneDropsOnlyDaysOlderThanTheCutoff()
	{
		KillStore s = new KillStore();
		s.record("Goblin", "2026-09-01");
		s.record("Goblin", "2026-09-24");
		s.record("Goblin", "2026-10-24");

		s.pruneBefore("2026-09-24");

		assertFalse(s.daily().containsKey("2026-09-01"));
		assertTrue(s.daily().containsKey("2026-09-24"));
		assertTrue(s.daily().containsKey("2026-10-24"));
		// All-time totals are never touched by pruning.
		assertEquals(3, s.all().get("Goblin").intValue());
	}

	@Test
	public void resetOneMonsterLeavesTheOthersAlone()
	{
		KillStore s = new KillStore();
		s.record("Goblin", "2026-10-24");
		s.record("Orc", "2026-10-24");
		s.record("Orc", "2026-10-25");

		s.reset("Goblin");

		assertFalse(s.all().containsKey("Goblin"));
		assertFalse(s.day("2026-10-24").containsKey("Goblin"));
		assertEquals(2, s.all().get("Orc").intValue());
		assertEquals(1, s.day("2026-10-25").get("Orc").intValue());
	}

